#!/usr/bin/env bash
# Prints a JWT for the shop stack's cyoda-go (client credentials from the developer's keychain).
set -eu
[ "${1:-}" = token ] || { echo 'usage: auth.sh token' >&2; exit 2; }
secret="$(security find-generic-password -s shop-cyoda -w)"
curl -sS -u "shop-dev:$secret" -d grant_type=client_credentials "$CYODA_ENDPOINT/api/oauth/token" | jq -r .access_token

